const splitBeforeNarrationLinks=$('splitClip').onclick;$('splitClip').onclick=()=>{const c=tracks().find(a=>a.id===selectedAudio);if(!c)return splitBeforeNarrationLinks();const before=structuredClone(project),old={...c},ids=new Set(tracks().map(a=>a.id));if(c.longVoiceGroupId&&narrationGroupClips(c).some(a=>a.locked))return toast('Unlock every narration section before splitting.');splitBeforeNarrationLinks();const added=tracks().find(a=>!ids.has(a.id));if(!added)return;const group=c.longVoiceGroupId||uid();for(const a of [c,added]){a.voiceLinkId=group;a.narrationSourceId=old.narrationSourceId||old.id}for(const s of project.scenes)for(const o of s.objects)if(o.speechTrackId===c.id)o.voiceLinkId=group;if(old.dialogueLineId){let root=narrationRoot(project,group);if(!root){const s=project.scenes.find(s=>s.id===old.dialogueSceneId),line=s&&storyLines(s).find(l=>l.id===old.dialogueLineId);if(line){line.longVoiceGroupId=group;line.longVoiceAnchorId=line.id;root={scene:s,line:structuredClone(line)}}}if(root){c.longVoiceGroupId=added.longVoiceGroupId=group;try{const source=narrationGroupClips(c),out=rebuildNarrationGroup(project,group,structuredClone(source),root);for(const a of out)if(!audioBuffers.has(a.id))audioBuffers.set(a.id,audioBuffers.get(old.id));if(!valid(project))throw Error('The split would leave invalid voice links.')}catch(e){Object.assign(project,before);toast(e.message)}}}save();render()};
